import json
n=17;m=n//2;g=[]
for r in range(n):
 row=[0]*n
 left=max(0,m-r); right=min(n-1,m+r)
 for c in range(n):
  # diagonal 1 lattice has phase equal to marker column mod 4;
  # before rays reach edges, it is restricted to the strict wedge interior.
  if (c-r-m)%4==0 and (r>=m or left<c<right):
   row[c]=1
 if r<=m:
  row[left]=2;row[right]=2
 g.append(row)
assert len(g)==17 and all(len(x)==17 for x in g) and all(set(x)<=set(range(10)) for x in g)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))
print('dimensions',len(g),[len(x) for x in g])

